/*
Theme Name: ImeniShop 24 Playground Demo
Author: ImeniShop 24 Prototype
Version: 1.1
Description: Persian RTL fire safety store prototype. All products are samples; no checkout.
*/
:root{--red:#b91c2b;--navy:#111d2f;--ink:#162236;--muted:#68758a;--bg:#f6f8fb;--line:#e7eaf0}
*{box-sizing:border-box}html{scroll-behavior:smooth}body{direction:rtl;margin:0;font-family:Tahoma,Arial,sans-serif;color:var(--ink);background:var(--bg);line-height:1.8}a{text-decoration:none;color:inherit}.wrap{width:min(1150px,calc(100% - 32px));margin:auto}.top{background:var(--navy);color:#dfe8f2;font-size:12px;padding:8px}.head{background:#fff;border-bottom:1px solid var(--line);position:sticky;top:0;z-index:10}.head-inner{display:flex;align-items:center;gap:28px;min-height:86px}.logo{color:var(--red);font-weight:900;font-size:25px;white-space:nowrap}.logo small{display:block;color:var(--muted);font-size:10px;line-height:1.5;font-weight:400}.nav{display:flex;gap:23px;align-items:center;flex-wrap:wrap;margin-inline-start:auto;font-size:13px;font-weight:600}.nav a:hover{color:var(--red)}.pill,.btn{display:inline-block;border-radius:12px;background:var(--red);padding:11px 20px;color:white;font-weight:700;font-size:13px}.btn.alt{background:#fff;color:var(--red)}.hero{background:linear-gradient(125deg,#b51b2a,#781021);color:#fff;position:relative;overflow:hidden}.hero:after{content:"✧";position:absolute;font-size:300px;color:rgba(255,255,255,.08);left:0;top:-110px}.hero-inner{position:relative;z-index:1;display:flex;align-items:center;gap:30px;padding:70px 0}.hero-content{flex:1}.eyebrow{font-size:12px;opacity:.86}.hero h1{font-size:clamp(26px,4vw,47px);line-height:1.45;margin:18px 0}.hero p{font-size:14px;max-width:610px;opacity:.92}.hero-art{width:260px;height:230px;display:grid;place-items:center;font-size:115px;filter:drop-shadow(0 20px 16px #5d0a1a)}.hero-actions{display:flex;gap:10px;margin-top:22px;flex-wrap:wrap}.notice{padding:11px 14px;border-radius:11px;background:#fff5e9;color:#8a520e;margin-top:18px;font-size:12px}.section{padding:42px 0 10px}.section-title{display:flex;justify-content:space-between;align-items:center;gap:14px;margin-bottom:19px}.section-title h2{font-size:24px;margin:0}.section-title span{font-size:12px;color:var(--muted)}.cats{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:13px}.cat{display:flex;align-items:center;gap:13px;padding:18px;background:#fff;border-radius:16px;border:1px solid var(--line);transition:.15s;min-height:87px}.cat:hover,.product:hover{transform:translateY(-2px);box-shadow:0 12px 28px rgba(31,47,77,.08)}.cat .emoji{background:#fcebed;border-radius:14px;min-width:45px;height:45px;display:grid;place-items:center;font-size:22px}.cat strong{font-size:13px}.cat small{display:block;font-size:10px;color:var(--muted)}.products{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:16px}.product{overflow:hidden;border-radius:18px;background:#fff;border:1px solid var(--line);transition:.15s}.product-cover{height:173px;background:linear-gradient(145deg,#fff3f3,#e9eff6);display:grid;place-items:center;font-size:76px}.product-body{padding:15px}.tag{background:#eaf8ef;color:#267348;border-radius:30px;font-size:10px;padding:3px 8px;display:inline-block}.product h3{font-size:13px;min-height:51px;line-height:1.8;margin:11px 0}.price{color:var(--red);font-size:16px;font-weight:900;margin:10px 0}.small{font-size:11px;color:var(--muted)}.product .see{border-top:1px solid var(--line);display:block;color:var(--red);font-weight:bold;text-align:center;font-size:12px;padding:12px}.info{margin:45px auto 32px;padding:26px;border-radius:19px;background:var(--navy);color:white;display:flex;align-items:center;justify-content:space-between;gap:20px}.info h2{margin:0;font-size:21px}.info p{margin:5px 0 0;color:#c1ccdc;font-size:12px}.foot{margin-top:42px;background:#121d2e;padding:35px 0;color:#c5d1e0;font-size:12px}.foot strong{font-size:20px;color:#fff}.footcols{display:flex;justify-content:space-between;gap:22px;flex-wrap:wrap}.pagearea{background:#fff;min-height:50vh;border:1px solid var(--line);border-radius:18px;margin-top:32px;padding:25px}.pagearea h1{margin:0 0 14px}.wp-block-button__link{background:var(--red)}.sample{background:#fff0f0;color:#aa1d2c;border:1px dashed #dc8692;border-radius:10px;padding:10px 15px;font-size:12px;margin:20px 0}.single-emoji{font-size:130px;background:#fff5f5;border-radius:20px;max-width:330px;text-align:center;padding:20px}.product-detail{display:flex;gap:30px;flex-wrap:wrap}.product-detail>div:last-child{flex:1;min-width:230px}
@media(max-width:900px){.products{grid-template-columns:repeat(3,minmax(0,1fr))}.cats{grid-template-columns:repeat(2,minmax(0,1fr))}.head-inner{flex-wrap:wrap;padding:12px 0;gap:8px;min-height:70px}.nav{gap:12px;font-size:11px}.hero-inner{padding:45px 0}.hero-art{width:150px;font-size:75px}}
@media(max-width:600px){.wrap{width:min(100% - 22px,1150px)}.top{font-size:10px}.head-inner{display:block;padding:12px 0}.logo{font-size:20px}.nav{margin-top:12px;gap:15px}.hero-inner{padding:37px 0}.hero-art{display:none}.hero h1{font-size:27px}.hero p{font-size:12px}.section{padding-top:29px}.section-title h2{font-size:19px}.cats{gap:8px}.cat{padding:11px;gap:7px;min-height:74px}.cat .emoji{min-width:35px;height:35px;font-size:18px}.cat strong{font-size:11px}.cat small{font-size:9px}.products{grid-template-columns:repeat(2,minmax(0,1fr));gap:9px}.product-cover{height:137px;font-size:60px}.product-body{padding:10px}.product h3{font-size:11px;min-height:58px}.price{font-size:13px}.info{display:block;margin:30px auto;padding:20px}.info .btn{margin-top:12px}.footcols{display:block}.pagearea{padding:16px}}
